//export w2n_getGasLeft
func w2n_getGasLeft(ctx *C.vm_exec_hook_context_t) C.vm_exec_hook_result_t {
	vmHooks, errorHandler := getVMHooksFromHookContext(ctx)
	result, err := vmHooks.GetGasLeft()
	if err != nil {
		return hookEarlyExit(errorHandler, err)
	}
	return hookOk(int64(result))
}

//export w2n_getSCAddress
func w2n_getSCAddress(ctx *C.vm_exec_hook_context_t, resultOffset int32) C.vm_exec_hook_result_t {
	vmHooks, errorHandler := getVMHooksFromHookContext(ctx)
	err := vmHooks.GetSCAddress(executor.MemPtr(resultOffset))
	if err != nil {
		return hookEarlyExit(errorHandler, err)
	}
	return hookOk(0)
}

